    gen: () => { const m = pick([20, 25, 30, 40, 50, 60, 100]); return N(`A ${m}% markup on cost equals what gross margin on price?`, pc(m / 100 / (1 + m / 100)), [`${m}%`, pc(m / 100 / (1 + m / 50)), pc(1 - m / 200)], 'Margin = markup ÷ (1 + markup).', 'Same profit, bigger base.'); },
