    ex: { p: 'Net income $40M, interest $10M, taxes $15M, depreciation $20M, amortization $5M. EBITDA?', s: ['Add back each item: 40 + 10 + 15 + 20 + 5.', 'EBITDA = $90M.'], a: '$90M.' },
    qs: [
      Q('A weakness of EBITDA is that it', ['ignores capital spending needed to keep the business running', 'includes interest', 'is required by GAAP', 'counts taxes twice'], 'Heavy-equipment businesses can look healthier than they are.', 'What does it leave out?'),
      Q('EBITDA is often used to', ['compare operating performance across companies with different debt levels', 'calculate exact cash in the bank', 'pay dividends directly', 'replace the balance sheet'], 'It strips financing and tax differences.', 'Compare operations.'),
    ],
    gen: () => { const ni = rnd(5, 80), i = rnd(1, 20), t = rnd(2, 25), d = rnd(3, 40); return N(`Net income $${ni}M, interest $${i}M, taxes $${t}M, D&A $${d}M. EBITDA?`, `$${ni + i + t + d}M`, [`$${ni + i + t}M`, `$${ni + d}M`, `$${ni - i - t - d < 0 ? ni + i : ni - i - t - d}M`], 'Add back interest, taxes, depreciation and amortization.', 'Add everything back.'); },
